components.css:
.ds-button-primary-surface { color-scheme: light; font: 400 16px/1.85 IRANYekanX, Vazirmatn, Segoe UI, Tahoma, system-ui, sans-serif; --bg-canvas: 249 250 251; --ring-brand: 97 114 243; --bg-brand-solid: 53 56 205; --bg-brand-solid-hover: 45 49 166; --fg-on-brand: 255 255 255; --brand-600: 53 56 205; --brand-800: 45 50 130; }
.ds-primary { display: inline-flex; box-sizing: border-box; min-height: 48px; align-items: center; justify-content: center; gap: 12px; padding: 12px 22px; border: 1px solid transparent; border-radius: 10px; font: inherit; font-size: 14px; font-weight: 600; line-height: 1.6; text-decoration: none; transition: background .16s ease-out, color .16s ease-out; }
.ds-primary { background: rgb(var(--bg-brand-solid)); color: rgb(var(--fg-on-brand)); }
.ds-primary:hover { background: rgb(var(--bg-brand-solid-hover)); }
.ds-primary:active { background: rgb(var(--brand-800)); }
.ds-primary:focus-visible { outline: 2px solid rgb(var(--brand-600)); outline-offset: 4px; box-shadow: 0 0 0 2px rgb(var(--bg-canvas)), 0 0 0 4px rgb(var(--ring-brand)); }
@media (prefers-reduced-motion: reduce) { .ds-primary { transition-duration: .01ms !important; } }

.ds-button-secondary-surface { color-scheme: light; font: 400 16px/1.85 IRANYekanX, Vazirmatn, Segoe UI, Tahoma, system-ui, sans-serif; --bg-canvas: 249 250 251; --ring-brand: 97 114 243; --bg-surface: 255 255 255; --border-primary: 208 213 221; --fg-secondary: 52 64 84; --bg-hover: 249 250 251; --fg-primary: 16 24 40; --brand-600: 53 56 205; }
.ds-secondary { display: inline-flex; box-sizing: border-box; min-height: 48px; align-items: center; justify-content: center; gap: 12px; padding: 12px 22px; border: 1px solid transparent; border-radius: 10px; font: inherit; font-size: 14px; font-weight: 600; line-height: 1.6; text-decoration: none; transition: background .16s ease-out, color .16s ease-out; }
.ds-secondary { border-color: rgb(var(--border-primary)); background: rgb(var(--bg-surface)); color: rgb(var(--fg-secondary)); }
.ds-secondary:hover { background: rgb(var(--bg-hover)); color: rgb(var(--fg-primary)); }
.ds-secondary:focus-visible { outline: 2px solid rgb(var(--brand-600)); outline-offset: 4px; box-shadow: 0 0 0 2px rgb(var(--bg-canvas)), 0 0 0 4px rgb(var(--ring-brand)); }
@media (prefers-reduced-motion: reduce) { .ds-secondary { transition-duration: .01ms !important; } }

.ds-button-auth-submit-surface { color-scheme: light; font: 400 16px/1.85 IRANYekanX, Vazirmatn, Segoe UI, Tahoma, system-ui, sans-serif; --bg-canvas: 249 250 251; --ring-brand: 97 114 243; --bg-brand-solid: 53 56 205; --bg-brand-solid-hover: 45 49 166; --fg-on-brand: 255 255 255; --brand-600: 53 56 205; --bg-disabled: 242 244 247; --fg-disabled: 152 162 179; --shadow-xs: 0 1px 2px 0 rgb(16 24 40 / 0.05); }
.ds-auth-submit { display: inline-flex; box-sizing: border-box; min-height: 50px; width: 100%; align-items: center; justify-content: center; gap: 8px; padding: 0 16px; border: 1px solid transparent; border-radius: 10px; background: rgb(var(--bg-brand-solid)); color: rgb(var(--fg-on-brand)); font: 600 15px/24px IRANYekanX, Vazirmatn, Segoe UI, Tahoma, system-ui, sans-serif; box-shadow: var(--shadow-xs); transition: color 150ms cubic-bezier(.4, 0, .2, 1), background-color 150ms cubic-bezier(.4, 0, .2, 1); }
.ds-auth-submit:hover, .ds-auth-submit:active { background: rgb(var(--bg-brand-solid-hover)); }
.ds-auth-submit:disabled { background: rgb(var(--bg-disabled)); color: rgb(var(--fg-disabled)); box-shadow: none; cursor: not-allowed; }
.ds-auth-submit:focus-visible { outline: 2px solid rgb(var(--brand-600)); outline-offset: 4px; box-shadow: 0 0 0 2px rgb(var(--bg-canvas)), 0 0 0 4px rgb(var(--ring-brand)), var(--shadow-xs); }
@media (prefers-reduced-motion: reduce) { .ds-auth-submit { transition-duration: .01ms !important; } }

.ds-button-auth-link-surface { color-scheme: light; font: 400 16px/1.85 IRANYekanX, Vazirmatn, Segoe UI, Tahoma, system-ui, sans-serif; --bg-canvas: 249 250 251; --ring-brand: 97 114 243; --fg-brand: 53 56 205; --brand-600: 53 56 205; --fg-disabled: 152 162 179; }
.ds-auth-link { display: inline-flex; min-height: 44px; align-items: center; justify-content: center; gap: 4px; padding: 0; border: 1px solid transparent; background: transparent; color: rgb(var(--fg-brand)); font: 600 14px/24px IRANYekanX, Vazirmatn, Segoe UI, Tahoma, system-ui, sans-serif; text-underline-offset: 4px; transition: color 150ms cubic-bezier(.4, 0, .2, 1); }
.ds-auth-link:hover { text-decoration: underline; }
.ds-auth-link:disabled { color: rgb(var(--fg-disabled)); cursor: not-allowed; }
.ds-auth-link:focus-visible { outline: 2px solid rgb(var(--brand-600)); outline-offset: 4px; box-shadow: 0 0 0 2px rgb(var(--bg-canvas)), 0 0 0 4px rgb(var(--ring-brand)); }
@media (prefers-reduced-motion: reduce) { .ds-auth-link { transition-duration: .01ms !important; } }

.ds-auth-phone-field-surface { color-scheme: light; font: 400 16px/1.85 IRANYekanX, Vazirmatn, Segoe UI, Tahoma, system-ui, sans-serif; --bg-surface: 255 255 255; --fg-primary: 16 24 40; --fg-secondary: 52 64 84; --fg-tertiary: 102 112 133; --fg-quaternary: 152 162 179; --fg-disabled: 152 162 179; --bg-disabled: 242 244 247; --border-primary: 208 213 221; --brand-600: 53 56 205; --ring-brand: 97 114 243; --error-600: 217 45 32; --error-700: 180 35 24; --shadow-xs: 0 1px 2px 0 rgb(16 24 40 / 0.05); }
.ds-phone { display: grid; gap: 6px; max-width: 400px; }
.ds-phone label { color: rgb(var(--fg-secondary)); font-size: 14px; font-weight: 500; line-height: 22px; }
.ds-phone-control { position: relative; display: flex; align-items: center; }
.ds-phone-symbol { position: absolute; display: flex; inset-inline-start: 12px; color: rgb(var(--fg-quaternary)); pointer-events: none; }
.ds-phone-prefix { position: absolute; inset-inline-end: 12px; color: rgb(var(--fg-secondary)); font-size: 12px; line-height: 20px; pointer-events: none; }
.ds-phone input { box-sizing: border-box; width: 100%; height: 50px; padding: 0 40px 0 64px; border: 1px solid rgb(var(--border-primary)); border-radius: 10px; background: rgb(var(--bg-surface)); color: rgb(var(--fg-primary)); font: 400 16px/24px IRANYekanX, Vazirmatn, Segoe UI, Tahoma, system-ui, sans-serif; box-shadow: var(--shadow-xs); transition: color 150ms cubic-bezier(.4, 0, .2, 1), border-color 150ms cubic-bezier(.4, 0, .2, 1); }
.ds-phone input::placeholder { color: rgb(var(--fg-tertiary)); opacity: 1; }
.ds-phone input:focus-visible { border-color: rgb(var(--brand-600)); box-shadow: 0 0 0 2px rgb(var(--ring-brand)), var(--shadow-xs); }
.ds-phone input[aria-invalid="true"] { border-color: rgb(var(--error-600)); }
.ds-phone input:disabled { background: rgb(var(--bg-disabled)); color: rgb(var(--fg-disabled)); cursor: not-allowed; }
.ds-phone-hint { margin: 0; color: rgb(var(--fg-tertiary)); font-size: 12px; line-height: 20px; }
.ds-phone-error { margin: 0; color: rgb(var(--error-700)); font-size: 13px; line-height: 1.9; }
.ds-phone input:focus-visible { outline: 2px solid rgb(var(--brand-600)); outline-offset: 0; }
@media (prefers-reduced-motion: reduce) { .ds-phone input { transition-duration: .01ms !important; } }

.ds-marketing-nav-link-surface { color-scheme: light; font: 400 16px/1.85 IRANYekanX, Vazirmatn, Segoe UI, Tahoma, system-ui, sans-serif; --bg-canvas: 249 250 251; --ring-brand: 97 114 243; --fg-secondary: 52 64 84; --fg-brand: 53 56 205; --brand-600: 53 56 205; }
.ds-nav { display: flex; align-items: center; justify-content: center; gap: 24px; }
.ds-nav a { box-sizing: border-box; min-height: 44px; padding-block: 14px; color: rgb(var(--fg-secondary)); font-size: 13px; text-decoration: none; text-underline-offset: 5px; }
.ds-nav a:hover, .ds-nav a[aria-current="page"] { color: rgb(var(--fg-brand)); }
.ds-nav a[aria-current="page"] { text-decoration: underline; text-decoration-thickness: 2px; }
.ds-nav a:focus-visible { outline: 2px solid rgb(var(--brand-600)); outline-offset: 4px; box-shadow: 0 0 0 2px rgb(var(--bg-canvas)), 0 0 0 4px rgb(var(--ring-brand)); }

.ds-preview-tab-selected-surface { color-scheme: light; font: 400 16px/1.85 IRANYekanX, Vazirmatn, Segoe UI, Tahoma, system-ui, sans-serif; --bg-canvas: 249 250 251; --ring-brand: 97 114 243; --fg-secondary: 52 64 84; --bg-hover: 249 250 251; --bg-brand-subtle: 238 244 255; --brand-200: 199 215 254; --fg-brand: 53 56 205; --brand-600: 53 56 205; --fg-tertiary: 102 112 133; }
.ds-preview-tabs { display: flex; justify-content: center; gap: 8px; flex-wrap: wrap; }
.ds-preview-tab { box-sizing: border-box; min-height: 44px; border: 1px solid transparent; border-radius: 8px; padding: 10px 18px; color: rgb(var(--fg-secondary)); background: transparent; font: inherit; font-size: 13px; }
.ds-preview-tab:hover { background: rgb(var(--bg-hover)); }
.ds-preview-tab[aria-selected="true"] { background: rgb(var(--bg-brand-subtle)); border-color: rgb(var(--brand-200)); color: rgb(var(--fg-brand)); font-weight: 600; }
.ds-preview-panel { margin-top: 16px; text-align: center; color: rgb(var(--fg-tertiary)); font-size: 13px; line-height: 2; }
.ds-preview-tab:focus-visible { outline: 2px solid rgb(var(--brand-600)); outline-offset: 4px; box-shadow: 0 0 0 2px rgb(var(--bg-canvas)), 0 0 0 4px rgb(var(--ring-brand)); }
.ds-preview-panel:focus-visible { outline: 2px solid rgb(var(--brand-600)); outline-offset: 4px; box-shadow: 0 0 0 2px rgb(var(--bg-canvas)), 0 0 0 4px rgb(var(--ring-brand)); }

.ds-status-badge-progress-surface { color-scheme: light; font: 400 16px/1.85 IRANYekanX, Vazirmatn, Segoe UI, Tahoma, system-ui, sans-serif; --status-progress: 181 71 8; --status-progress-bg: 255 250 235; --status-progress-border: 254 223 137; }
.ds-progress-badge { display: inline-flex; box-sizing: border-box; align-items: center; height: 20px; gap: 4px; padding-inline: 6px; border: 1px solid rgb(var(--status-progress-border)); border-radius: 9999px; color: rgb(var(--status-progress)); background: rgb(var(--status-progress-bg)); font-size: 11px; font-weight: 500; line-height: 18px; white-space: nowrap; }
.ds-progress-dot { flex: 0 0 6px; height: 6px; border-radius: 9999px; background: rgb(var(--status-progress)); }

.ds-status-badge-done-surface { color-scheme: light; font: 400 16px/1.85 IRANYekanX, Vazirmatn, Segoe UI, Tahoma, system-ui, sans-serif; --status-done: 2 122 72; --status-done-bg: 236 253 243; --status-done-border: 166 244 197; }
.ds-done-badge { display: inline-flex; box-sizing: border-box; align-items: center; height: 20px; gap: 4px; padding-inline: 6px; border: 1px solid rgb(var(--status-done-border)); border-radius: 9999px; color: rgb(var(--status-done)); background: rgb(var(--status-done-bg)); font-size: 11px; font-weight: 500; line-height: 18px; white-space: nowrap; }
.ds-done-dot { flex: 0 0 6px; height: 6px; border-radius: 9999px; background: rgb(var(--status-done)); }

.ds-sample-task-surface { color-scheme: light; font: 400 16px/1.85 IRANYekanX, Vazirmatn, Segoe UI, Tahoma, system-ui, sans-serif; --status-progress: 181 71 8; --status-progress-bg: 255 250 235; --status-progress-border: 254 223 137; --bg-surface: 255 255 255; --border-secondary: 234 236 240; --fg-primary: 16 24 40; --fg-tertiary: 102 112 133; --brand-100: 224 234 255; --brand-700: 45 49 166; }
.ds-task { min-width: 0; padding: 16px; border: 1px solid rgb(var(--border-secondary)); border-radius: 10px; background: rgb(var(--bg-surface)); color: rgb(var(--fg-primary)); }
.ds-task-top, .ds-task-bottom { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.ds-task-top > span:last-child { color: rgb(var(--fg-tertiary)); font-size: 10px; }
.ds-task h3 { margin: 16px 0 0; font-size: 13px; font-weight: 600; line-height: 1.9; }
.ds-task p { margin: 6px 0 0; color: rgb(var(--fg-tertiary)); font-size: 11px; line-height: 1.9; }
.ds-task-bottom { margin-top: 18px; }
.ds-task-bottom > span:first-child { display: inline-flex; align-items: center; gap: 5px; color: rgb(var(--fg-tertiary)); font-size: 10px; }
.ds-task-avatar { display: inline-grid; place-items: center; width: 24px; height: 24px; border-radius: 9999px; background: rgb(var(--brand-100)); color: rgb(var(--brand-700)); font-size: 10px; font-weight: 600; box-shadow: inset 0 0 0 1px rgb(0 0 0 / .04); }
.ds-task-badge { display: inline-flex; box-sizing: border-box; align-items: center; height: 20px; gap: 4px; padding-inline: 6px; border: 1px solid rgb(var(--status-progress-border)); border-radius: 9999px; color: rgb(var(--status-progress)); background: rgb(var(--status-progress-bg)); font-size: 11px; font-weight: 500; line-height: 18px; white-space: nowrap; }
.ds-task-dot { flex: 0 0 6px; height: 6px; border-radius: 9999px; background: rgb(var(--status-progress)); }
